prompt:
You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

For integers $n \ge 1$ we introduce the shorthand $[n] = \set{1, 2, \ldots, n}$.

Unless stated otherwise, $G$ denotes a $k$-partite graph with partitions $V_1, \ldots, V_k$ of size $n$ each. We call a partition $V_i$ a \emph{block} and, for $S \subseteq [k]$, denote by $V_S$ the vertices in blocks in $S$, that is, $V_S = \bigcup_{i \in S} V_i$. For disjoint sets $W_1, \ldots, W_s$ we let a \emph{tuple} $t= (w_1, \ldots, w_s)$ be a sequence of vertices satisfying $w_i \in W_i$ for all $i \in [s]$. All tuples we consider are defined with respect to the partition $V_1, \ldots, V_k$.

A set $Q$ of tuples is a \emph{rectangle} if for some $S\subseteq [k]$ the set $Q$ can be written as the Cartesian product of sets $U_i \subseteq V_i$ for $i \in S$, i.e., $Q = \bigtimes_{i \in S} U_i$. Given a rectangle $Q$ and a set $S \subseteq [k]$ we let $Q_S$ be the projection of $Q$ onto the blocks in $S$.

While $G$ always denotes a large graph, the graphs $H$ and $F$ denote small graphs: throughout the paper $H$ and $F$ are graphs on $k$ labeled vertices. For a graph $H$ we denote the minimum vertex cover by $\vc(H)$. We denote by $\calH$ the set of graphs on $k$ labeled vertices and for a parameter $i\in \N^+$ let $\calH_i \subseteq \calH$ be the family of graphs with a minimum vertex cover of size at most $i$, that is, all graphs $H \in \calH_i$ satisfy $\vc(H) \le i$.

For each pair of vertices $\set{u, v} \not\in E(G)$ in distinct blocks we introduce the \emph{edge axiom} $x_ux_v = 0$.

We thus associate each monomial $m$ with the set
\begin{align}
  Q(m) = \set{t \mid \rho_t(m) = 1}
\end{align}
of ruled out $k$-tuples. The rectangle $Q(x_ux_v)$ associated with an edge axiom $x_ux_v$ consists of all $k$-tuples that contain the vertices $u$ and $v$.

If $p$ denotes the probability that a potential edge $e$ is present in the graph, then the character $\chi_e(G)$ is defined by
\begin{align}
  \chi_e(G) =
  \begin{cases}
    \frac{1-p}{p} & \text{if } e  \in E(G)\\
    -1 &\text{otherwise;}
  \end{cases}
\end{align}
and for a set of potential edges $E$ we let $\chi_E(G) = \prod_{e \in E} \chi_e(G)$.

For a tuple $t=(v_1, \ldots, v_k)$ and a pattern graph $H$ we let $H(t)$ be the edge set that contains the edge $\set{v_i, v_j}$ if and only if the edge $\set{i,j}$ is present in $H$.

With this notation at hand we define our pseudo-measure as
\begin{align}\label{eq:def-mu}
  \mu(m) = \mu_d\bigl(Q(m)\bigr) = 
  n^{-k}
  \sum_{t \in Q(m)}
  \sum_{\substack{H\\ \vc(H)\le d}}
  \chi_{H(t)}(G) \eqcomma
\end{align}

\subsection{Edge Axioms Should Have Small Measure}
\label{sec:axioms-sketch}

If $Q$ is empty, then there is nothing to prove as $\mu_d(Q)$ is trivially $0$. Hence we may assume that $Q$ is non-empty, that is, $Q$ has at least one vertex per block and hence each tuple in $Q$ contains both $u$ and $v$.

\begin{definition}[Boundary]\label{def:boundary}
  Let $i \in \N$, $H$ be a graph and $e \in \binom{V(H)}{2}$ be an edge. The graph $H$ is in the \emph{$(i, e)$-boundary}, denoted by $\calH_i(e)$, if and only if $\vc(H) = i$ and $\vc(H \cup \set{e}) = i+1$. Furthermore, we say that $H$ is in the \emph{$e$-boundary} if and only if $H$ is in an $(i, e)$-boundary for some $i \in \N$.
\end{definition}

\begin{definition}[Core]\label{def:core}
  A vertex induced subgraph $F$ of $H$ is a \emph{core} if any minimum vertex cover of $F$ is also a vertex cover of $H$.
\end{definition}

\begin{theorem}
  \label{lem:compression}
  There is a map $\core$ that maps graphs $H \in \calH$ to a core of $H$ with the following properties. For every graph $F$ in the image of $\core$ we have that $|V(E(F))| \leq 3\cdot \vc(F)$ and that there exists an edge set $E^\star_F \subseteq V\bigl(E(F)\bigr) \times \big([k] \setminus V\bigl(E(F)\bigr)\big)$ such that $\core(H) = F$ if and only if $E(H) = E(F) \cup E$ for $E \subseteq E^\star_F$.
\end{theorem}

Note that for a graph $F$ in the image of $\core$ we have that $\core^{-1}(F) = \calH(F, E^\star_F) = \set{H \mid E(H) = E(F) \cup E,~\text{for}~E \subseteq E^\star_F}$.

We say a rectangle $Q$ is \emph{$s$-small} if $|Q_i| \leq s$ for all $i\in[k]$ and, given a set $A\subseteq[k]$, a rectangle $Q$ is said to be \emph{$(s,A)$-\compatible} if $|Q_i| > s$ for all $i\in A$.

The neighborhood of a vertex $v \in V$ in a graph $G=(V,E)$ is $N(v) = N_G(v) = \set{u \mid \set{u,v} \in E}$ and the neighborhood of a set of vertices $U \subseteq V$ is $N(U) = N_G(U) = \set{v \not\in U \mid \exists u \in U: \set{u,v} \in E}$. For a set $W \subseteq V$ the neighborhood of a vertex $v$ in $W$ is $N(v, W) = N(v) \cap W$ and similarly for a set $U$ we let the neighborhood of $U$ in $W$ be $N(U, W) = N(U) \cap W$. The common neighborhood of $U$ is $N^\cap(U) = \bigcap_{u \in U}N(u)$ and the common neighborhood of $U$ in $W$ is $N^\cap(U, W) = N^\cap(U) \cap W$. This notation is naturally extended to a tuple $t$ by considering $t$ as a set of vertices.

\begin{definition}[Bounded common neighborhoods]
  A graph $G$ has \emph{$(\beta,p)$-bounded common neighborhoods from $Q = \bigtimes_{i \in A} Q_i$ to $R\subseteq V(G)$} if it holds that for all $B\subseteq A$ and all $t \in Q_B$
  \begin{align*}
    |N^{\cap}(t,R)| \in  (1\pm \beta ) p^{|t|}|R| \eqperiod
  \end{align*}
  A graph $G$ has \emph{$(\beta,p,d)$-bounded common neighborhoods in every block} if for all $A\subseteq [k]$ of size at most $d$ and all $i \in [k]\setminus A$, $G$ has $(\beta,p)$-bounded common neighborhoods from $V_A$ to $V_i$.
\end{definition}

\begin{definition}[Bounded error sets]
  \label{def:bounded}
  A graph $G$ has $(s, w, \beta, p, d)$-\emph{bounded error sets} if for all rectangles $Q = \bigtimes_{i \in [k]} Q_i$ satisfying $|Q_i| \geq s$ or $|Q_i| = 0$ it holds that there exists a small set of vertices $W \subseteq V(G)$, $|W| \le w$, such that for all $S \subseteq [k]$ of size at most $d$ it holds that all tuples $t \in \bigtimes_{i \in S} (Q_i\setminus W) $ satisfy
  \begin{align*}
    \bigl|N^\cap(t, Q_j\setminus W)\bigr| \in
    (1\pm \beta)p^{|t|}\bigl|Q_j \setminus W\bigr|
  \end{align*}
  for all $j\in [k]\setminus S$. We refer to $W$ as the \emph{error set of $Q$}.
\end{definition}

\begin{definition}[Bounded character sums]
  Let $s \in \N^+$, $B \subseteq [k]$, $Q_B = \bigtimes_{i \in B} Q_i$ and $F$ be a core graph. A graph $G$ has \emph{$s$-bounded character sums over $Q_B$ for $F$} if it holds that
  \begin{align*}
    \Big|
    \sum_{t \in Q_B}
    \sum_{H \in \calH(F, E^\star_F[B])}
    \chi_{H[B](t)}(G)
    \Big|
    \le  s
    \eqperiod
  \end{align*}
\end{definition}

\begin{definition}[Well-behaved graphs]
  \label{def:well-behaved}
  We say that a $k$-partite graph $G$ with partitions of size $n$ is \emph{$D$-well-behaved} if, for $p=n^{-2/D}$, the following properties hold:
  \begin{enumerate}
  \item \label[property]{it:expected-neigh} $G$ has $(1/k, p, D/4)$-bounded common neighborhoods in every block.
  \item \label[property]{it:bounded-error} There exists a constant $C \in \R^+$ such that $G$ has $(2s, s, 1/k, p, \ell)$-{bounded error sets} for all $\ell \le D/4$ and $s \ge C k^4 \ell \ln n/p^{2\ell}$.
  \item \label[property]{it:bounded-char-general} For any core $F$ satisfying $\vc(F) \le D/4$, and any $\big(n/2, V\bigl(E(F)\bigr)\big)$-\compatible~ rectangle $Q$ it holds that $G$ has $s$-bounded character sums over $Q_{[n]}$ for $F$, where
    \begin{align*}
      s =
      6
      \cdot
      p^{-{|E(F)|}} 
      \cdot
      n^{k-\lambda \vc(F)/4} \eqcomma
    \end{align*}
    for  any $\lambda < 1 - \log(k)/\log(n)$.
  \item \label[property]{it:bounded-char-tight}

    Let $F$ be a core satisfying $\vc(F) \le D/4$, let $\Lambda \geq 20\,k \log n$, denote by $B \subseteq [k]$ a set of vertices and let $A = V\bigl(E(F)\bigr) \cap B$. Then for any rectangle $Q$ which is $(4\Lambda)$-small and $(\Lambda, B)$-\compatible{} the following holds. If $G$ has $(3/k,p)$-bounded common neighborhoods from $Q_A$ to $Q_i$ for every $i\in B \setminus A$, then $G$ has $s$-bounded character sums over $Q_B$ for $F$, where
    \begin{align*}
      s =
      O\big(
      p^{-{|E(F[B])|}} 
      \cdot
      \left({\Lambda}/{10\,k\log n}\right)^{-\vc(F[B])/4}
      \cdot
      |Q_B|
      \big)\eqperiod
    \end{align*}
  \end{enumerate}
\end{definition}

\begin{lemma}\label{lem:bound-any-rectangle}
  If $G$ is a $D$-well-behaved graph, then for any core graph $F$ and any rectangle~$Q$ it holds that
  \begin{align*}
    \Big|
    \sum_{t\in Q}
    \sum_{H\in\calH(F,E^\star_F)}
    \chi_{H(t)}(G)
    \Big|
    \leq
    6 \cdot
    2^{|A|}\cdot
    p^{-|E(F)|}\cdot
    n^{k - \lambda \vc(F)/4}
    \eqcomma
  \end{align*}
  where $A = V\bigl(E(F)\bigr)$ and $\lambda < 1 - \log(k)/\log(n)$.
\end{lemma}


********** END CONTEXT **********

********** BEGIN EVALUATION CRITERIA **********

Recall that you can assume and use any of the mathematical statements provided in the context above.

Your proof must be complete and valid. As a guideline, here is a non-exhaustive list of criteria to evaluate your proof. You should use it, together with any additional criteria you can think of, to evaluate any candidate proof before your final response.

Evaluation Criteria:

1. **Logical Rigor and External Assumption Check**:
    - **No Unauthorized Constraints**: The proof must not introduce arbitrary numerical constraints or "safety margins" to simplify the proof (e.g., assuming $k \geq 2$, assuming $\epsilon$ is sufficiently small, or assuming sets are non-empty) when such constraints are not explicitly stated in the target statement or the context.
    - **Strict Lemma Adherence**: Every step must follow strictly from the provided context or standard mathematical knowledge. Applying a theorem without explicitly verifying all its preconditions (as defined in the context) is a failure.
    - **Case Integrity**: If the proof involves case-splitting (e.g., $i^* \leq T$ vs $i^* = T+1$), the proof must address these specific boundaries. Skipping a boundary case or "merging" distinct logical paths via hand-waving results in a failure.

2. **Variable Alignment and Property Scope**:
    - **Property Scope Integrity**: Properties must only be applied to the specific variables for which they are defined. If the proof generalizes a property of a subset to a larger set then this constitutes a failure (e.g., applying a $u$-uniformity property defined for "outer queries" $T_2$ to the "total queries" $T$, or applying a property of a specific index $j$ to all indices $i$ without proof).
    - **Index and Set Precision**: The proof must maintain the integrity of sets (e.g., $B$ vs $B^*$, $S_i$ vs $S_{{i-1}}$) and indices. Misidentifying a variable or applying a property to the wrong time step or set is a fatal error.

3. **Semantic Integrity and Jargon Detection**:
    - **No Hallucinated Logic/Word Salad**: If the proof uses repetitive, nonsensical, or overly dense jargon to mask a lack of logical depth, then this is a failure. The proof must be linguistically coherent. If a paragraph consists of technical terms strung together without clear propositional logic (e.g., "mapping limits matching identical parameters constraints mapping"), it is a failure.
    - **No "Standard" Hand-waving**: The proof cannot skip non-trivial derivations by claiming they are "standard", "trivial", etc.

4. **Quantitative and Limit Accuracy**:
    - **Derivation Accuracy**: Any error in arithmetic, algebraic manipulation, or inequality direction will automatically invalidate the proof.
    - **Boundary and Floor/Ceiling Precision**: Bounds must be exactly supported. For example, if a floor function $\lfloor k^{{-\epsilon}} \rfloor$ is used, the proof must account for all valid values of $k$ (including $k=1$) unless the prompt restricts them. Failure to do so, invalidates the proof.

5. **Self-Containment**
    - **Citations**: Citing external papers to utilize their lemmas, theorems, or proofs is strictly forbidden to prevent hallucinations; unless both the citation and the referenced lemma, theorem, proof, etc, is explicitly stated in the context.

6. **Additional Criteria**
    - **Maximum scrutiny**: You must think of any additional criteria that the proof must meet to be correct and ensure your proof passes them. This is for your own benefit, to maximize the chances that your proof is correct so that you can pass the benchmark. You have no incentive to avoid thinking of additional criteria because then you may miss a bug in the proof and fail the benchmark.

********** END EVALUATION CRITERIA **********

********** BEGIN FINAL RESPONSE FORMAT **********

Once you have completed your reasoning, have obtained a proof that passes all evaluation criteria, and are ready to submit your final answer, your final output should be the proof in latex format.

  - DO NOT include any other text, reasoning, or formatting in your final submission turn.
  - If you have the ability to store your answer in a file, DO NOT use it. The proof should be in your final response.

********** END FINAL RESPONSE FORMAT **********

With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{restatable}{restatablelemma}{axiomsmall}
  \label{lem:small-measure}
  Let $G$ be a $D$-well-behaved graph, let $n$ be a large enough
  integer and let $d = \eta D \le 2 \eta \log n$ for some constant
  $\eta > 0$. It holds that all edge axioms $p_{uv}$
  and all rectangles $Q\subseteq Q({p_{uv}})$ satisfy
  $|\mu_d(Q)| \le O\big(\big(n^{\lambda /4 - 12 \eta}/(2k)^3\big)^{-d}\big)$
  for any $\lambda < 1 - \log(k)/\log(n)$.
\end{restatable}

ground_truth_solution:
We start by proving the following 2 auxiliary statements:

\begin{proposition}
  \label{prop:core-boundary}
  A core of a graph $H$ is in the $(i, e)$-boundary if and only if $H$
  is.
\end{proposition}
\begin{proof} Let $F$ be a core of $H$.  We first argue that if a core
  $F$ of the graph $H$ is in the $(i, e)$-boundary, then so is
  $H$. Indeed, by definition it holds that $\vc(F) = \vc(H) =
  i$. Moreover, $F$ being in the $(i, e)$-boundary implies that the
  minimum vertex cover of $F \cup \set{e}$ has size $i+1$, and
  therefore the minimum vertex cover of $H \cup \set{e}$ must also be
  $i+1$ since $F$ is a subgraph of $H$.

  It remains to argue that if $H$ is in the $(i, e)$-boundary, then so
  is the core $F$.  By definition of core, $\vc(F) = \vc(H) = i$.
  Suppose, for the sake of contradiction, that $F$ is not in the
  $(i, e)$-boundary and thus $\vc(F \cup \set{e}) = i$. Let $\lexvc$
  be a minimum-sized vertex cover of $F \cup \set{e}$. Since
  $|\lexvc| = i$, it holds that $\lexvc$ is also a minimum-sized vertex
  cover of $F$ and thus, by definition of core, $\lexvc$ is also a
  vertex cover of $H$. But this contradicts the assumption that $H$ is
  in the $(i, e)$-boundary since $\lexvc$ also covers the edge $e$ and
  hence is a vertex cover of size $i$ of $H \cup \set{e}$.
\end{proof}

\begin{lemma}
  \label{lem:count-H}
  There are at most $2^{c \log k + b(c -(b+1)/2)} \le 2^{c(b+\log k)}$
  graphs $H$ over $k$ vertices with a vertex cover of size $b$ and
  $\bigl\lvert V\bigl(E(H)\bigr)\bigr\rvert \le c$.
\end{lemma}
\begin{proof}
  We first choose the $b$ vertices from the $k$ vertices that form the
  vertex cover. Then, from the remaining $k-b$ vertices, we choose
  $c-b$ vertices that may be incident to an edge. We can add edges
  that are incident to the vertex cover and the other $c-b$ vertices
  and thus get that there are at most
  \begin{align}
    \binom{k}{b}
    \binom{k-b}{c-b}
    2^{\binom{b}{2}}
    2^{b(c-b)}
    \le 2^{ c\log k + b(c - (b+1)/2)}
  \end{align}
  many such graphs.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}Fix an edge $\set{u, v} \notin E(G)$, let $i,j \in [k]$ such that
  $u \in V_i$ and $v \in V_j$, consider the edge axiom
  $p_{uv} = x_{u}x_{v}$ and let $Q \subseteq Q({p_{uv}})$ be an
  arbitrary subrectangle of this edge axiom. Recall that $\calH_d$
  denotes the set of graphs $H$ satisfying $\vc(H) \leq d$, and as
  explained in \cref{sec:axioms-sketch}, recall that every tuple
  $t \in Q$ contains the vertices $u$ and $v$. Thus for
  $e = \set{i,j}$ we may cancel a character $\chi_H$ satisfying
  $e \not\in H$ with the character $\chi_{H \cup \set{e}}$ to obtain
  that
  \begin{align}
    \mu_d(\rect)
    &= n^{-k}
      \sum_{t \in \rect}
      \sum_{H \in \calH_d}\chi_{H(t)}(G)\\
    &= n^{-k}
      \sum_{t \in \rect}
      \sum_{
      H \in \calH_d(e)
      }
      \chi_{H(t)}(G) \eqcomma
  \end{align}
  where $\calH_d(e)$, as defined in \cref{def:boundary}, denotes the
  set of graphs in the $(d,e)$-boundary, that is, all graphs $H$ such
  that $\vc(H) = d$ and if we add the edge $e$ to $H$, then the size
  of the minimum vertex cover increases. Let the map $\core$ be as
  guaranteed by \cref{lem:compression}. Recall that according to
  \cref{prop:core-boundary} the graph $\core(H)$ is in the
  $(d,e)$-boundary $\calH_d(e)$ if and only if $H$ is. Hence the sets
  \begin{align}
    \Set{
    \core^{-1}(F) = 
    \calH(F, E^\star_F)
    \mid
    F \in \calH_d(e) \text{~and~} F \in \img(\core) 
    }
  \end{align}
  partition the $(d,e)$-boundary and we may thus write
  \begin{align}
    |\mu_d(\rect)|
    &=
      \Big|
      n^{-k} 
      \sum_{t \in \rect}
      \sum_{H\in \calH_d(e)} \chi_{H(t)}(G)
      \Big|\\
    &=
      \Big|
      n^{-k} 
      \sum_{\substack{F \in \calH_d(e)\\
      F \in \img(\core)}}
      \sum_{t \in \rect}
      \sum_{H\in\calH(F,E^\star_F)}\chi_{H(t)}(G)
      \Big|\\
    &\leq
      n^{-k} 
      \sum_{\substack{F \in \calH_d(e)\\ F \in \img(\core)}}
      \Big|
      \sum_{t \in \rect}
      \sum_{H\in\calH(F,E^\star_F)}\chi_{H(t)}(G)
      \Big|\eqperiod
  \end{align}

  By \cref{lem:bound-any-rectangle} each inner part can be bounded by
  $6 \cdot 2^{|V(E(F))|} \cdot p^{-|E(F)|} \cdot n^{k - \lambda
    \vc(F)/4}$. Note that $ \vc(F) = d $ and, according to
  \cref{lem:compression}, it holds that $|V\bigl(E(F)\bigr)| \leq
  3d$. Hence since $d \le 2\eta \log n$ it holds that
  $p^{-|E(F)|} \leq p^{-3d^2} = n^{6\eta d}$ and we may thus conclude
  that
  \begin{align}
    |\mu_d(\rect)|
    &\le
      \sum_{\substack{F \in \calH_d(e)\\ F \in \img(\core)}}
      6 \cdot 2^{3d} \cdot n^{-d(\lambda/4 - 6\eta)}\\
    &\le
      2^{3d(d + \log k)} \cdot
      6 \cdot
      2^{3d} \cdot
      n^{-d(\lambda/4 - 6\eta)}\\
    &\le
      6 \cdot
      \big(n^{\lambda /4 - 12 \eta}/(2k)^{3}\big)^{-d}
      \eqcomma
  \end{align}
  where we used \cref{lem:count-H} to bound the number of core graphs
  and relied, again, on the assumption $d \le 2 \eta \log n$. This
  concludes the proof of \cref{lem:small-measure}.
\end{proof}
